import Foundation
import Testing
import GlyphRecognitionImages
@testable import GlyphRecognition

@Suite("Recorded Glyph presentation", .enabled(if: ReferenceData.shapesAvailable))
struct RecordingRecognitionTests {
    private func image(at milliseconds: Int) throws -> LuminanceImage {
        try ImageDecoder.load(ReferenceData.fixturesDirectory
            .appendingPathComponent("Recording/sample-\(milliseconds).png"))
    }

    // Shapes and edges annotated by viewing the recording's presentation slots.
    // These are not generated by the recognizer or by sequence predictions.
    private var cases: [(time: Int, glyph: String, edges: Set<String>)] { [
        (25500, "see", ["0-3"]),
        (25900, "truth", ["3-5", "3-6", "4-5", "4-7", "5-6", "5-7"]),
        (26300, "see", ["0-3"]),
        (26700, "future", ["2-4", "4-7", "7-9"]),
        (27100, "begin", ["0-6", "6-a", "7-a"])
    ] }

    @Test("All five real presented Glyphs match their manually annotated edges")
    func realPresentation() throws {
        let blank = try image(at: 25150)
        let fit = try #require(NodeArrayDetector().detect(in: blank))
        let recognizer = GlyphFrameRecognizer(table: try ReferenceData.glyphTable())
        #expect(fit.matchedNodes.count == 11)
        #expect(recognizer.observe(blank, calibration: fit).state == .noStroke)
        for sample in cases {
            let observation = recognizer.observe(try image(at: sample.time), calibration: fit)
            #expect(observation.state == .uniqueVisibleShape, "\(sample.time): \(observation.state)")
            #expect(observation.exactMatches == [GlyphID(sample.glyph)])
            #expect(Set(observation.edges.map { "\($0.lower)-\($0.upper)" }) == sample.edges)
            #expect(observation.unexplainedInkPixelCount < observation.strokePixelCount / 5)
        }
    }

    @Test("Manual presentation boundaries preserve the repeated see and resolve the sequence", .enabled(if: ReferenceData.sequencesAvailable))
    func confirmedSlotsPredict() throws {
        let fit = try #require(NodeArrayDetector().detect(in: image(at: 25150)))
        let recognizer = GlyphFrameRecognizer(table: try ReferenceData.glyphTable())
        let predictor = SequencePredictor(table: try ReferenceData.sequenceTable())
        var accumulator = GlyphStrokeAccumulator(calibration: fit, recognizer: recognizer)
        var observed: [GlyphID] = []
        for sample in cases {
            let frame = try image(at: sample.time)
            try accumulator.append(frame)
            let provisional = accumulator.finish()
            #expect(provisional?.acceptedGlyph == nil)
            try accumulator.append(frame)
            // The external annotation confirms the slot ended. Pixels alone do not.
            let completed = accumulator.finish(completion: .presentationBoundary)
            let glyph = try #require(completed?.acceptedGlyph)
            observed.append(glyph)
            #expect(glyph == GlyphID(sample.glyph))
            #expect(!predictor.predict(observed: observed).isContradicted)
        }
        #expect(observed.map(\.name) == ["see", "truth", "see", "future", "begin"])
        let prediction = predictor.predict(observed: observed)
        #expect(prediction.isResolved)
        #expect(prediction.remaining.isEmpty)
        // Four observed Glyphs still leave a terminal-prefix ambiguity in the
        // table. Knowing five slots exist would be additional game-state input.
        let afterFour = predictor.predict(observed: Array(observed.prefix(4)))
        #expect(!afterFour.isResolved)
        #expect(afterFour.observationMayBeComplete)
    }

    @Test("Recorded command/input trails are diagnosed rather than accepted as clean shapes")
    func trailsOutsidePresentation() throws {
        let fit = try #require(NodeArrayDetector().detect(in: image(at: 25150)))
        let recognizer = GlyphFrameRecognizer(table: try ReferenceData.glyphTable())
        for time in [23600, 28550] {
            let observation = recognizer.observe(try image(at: time), calibration: fit)
            #expect(observation.state == .unexplainedInk)
            #expect(!observation.hasUniqueVisibleShape)
        }
        // This is an image-quality check, not a game-phase classifier. Cleaner
        // player input could still match and must be excluded by phase tracking.
    }

    @Test("Live session acquires empty geometry and reuses it across all five presented shapes")
    func liveSession() throws {
        var session = GlyphFrameSession(table: try ReferenceData.glyphTable())
        #expect(session.observe(try image(at: 25150), at: 25.15)?.state == .noStroke)
        let original = try #require(session.calibration)
        for sample in cases {
            let result = session.observe(try image(at: sample.time), at: Double(sample.time) / 1000)
            #expect(result?.state == .uniqueVisibleShape)
            #expect(result?.exactMatches == [GlyphID(sample.glyph)])
            #expect(session.calibration == original)
        }
    }

    @Test("Live calibration is invalidated by gaps, clock reversal, dimensions and explicit reset")
    func liveInvalidation() throws {
        let blank = try image(at: 25150)
        let glyph = try image(at: 25500)
        var session = GlyphFrameSession(table: try ReferenceData.glyphTable())
        #expect(session.observe(blank, at: 1)?.state == .noStroke)
        #expect(session.observe(glyph, at: 1.1)?.exactMatches == [GlyphID("see")])
        #expect(session.observe(glyph, at: 3) == nil)
        #expect(session.calibration == nil)
        #expect(session.observe(blank, at: 4)?.state == .noStroke)
        #expect(session.observe(glyph, at: 2) == nil)
        #expect(session.observe(blank, at: 5)?.state == .noStroke)
        let resized = try LuminanceImage(width: 20, height: 40, pixels: [UInt8](repeating: 0, count: 800))
        #expect(session.observe(resized, at: 5.1) == nil)
        #expect(session.calibration == nil)
        #expect(session.observe(blank, at: 6)?.state == .noStroke)
        session.reset()
        #expect(session.observe(glyph, at: 6.1) == nil)
        #expect(session.observe(blank, at: .nan) == nil)
    }

    @Test("Cached calibration expires without an independently detected empty array")
    func liveExpiry() throws {
        var session = GlyphFrameSession(table: try ReferenceData.glyphTable())
        let glyph = try image(at: 25500)
        #expect(session.observe(try image(at: 25150), at: 0)?.state == .noStroke)
        for step in 1...80 {
            #expect(session.observe(glyph, at: Double(step) / 10)?.exactMatches == [GlyphID("see")])
        }
        #expect(session.observe(glyph, at: 8.1) == nil)
        #expect(session.calibration == nil)
        #expect(session.observe(try image(at: 25150), at: 8.2)?.state == .noStroke)
        #expect(session.observe(glyph, at: 8.3)?.exactMatches == [GlyphID("see")])
    }
}
